import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, BoxGeometry, PlaneGeometry, ShapeGeometry, Box3, Vector3 } = THREE;

  const root = new Group();
  root.name = 'nova-atelier-thumbnail-card';

  const timelines = [];
  const primitiveCleanups = [];
  const ownedResources = [];

  const surfaceMaterial = new MeshBasicNodeMaterial({ color: '#0b0b10' });
  const inkMaterial = new MeshBasicNodeMaterial({ color: '#16161d' });
  const paperMaterial = new MeshBasicNodeMaterial({ color: '#e8ecf2' });
  const accentMaterial = new MeshBasicNodeMaterial({ color: '#ff2a38' });

  ownedResources.push(surfaceMaterial, inkMaterial, paperMaterial, accentMaterial);

  const backing = new Mesh(
    new BoxGeometry(2.85, 2.05, 0.12),
    surfaceMaterial
  );
  backing.name = 'thumbnail-card-surface';
  backing.position.z = -0.16;
  root.add(backing);
  ownedResources.push(backing.geometry);

  const captionStrip = new Mesh(
    new BoxGeometry(2.72, 0.42, 0.08),
    inkMaterial
  );
  captionStrip.name = 'caption-strip';
  captionStrip.position.set(0, -0.7, -0.03);
  root.add(captionStrip);
  ownedResources.push(captionStrip.geometry);

  const topEdge = new Mesh(
    new BoxGeometry(2.86, 0.035, 0.035),
    accentMaterial
  );
  topEdge.name = 'accent-focus-edge';
  topEdge.position.set(0, 0.88, 0.06);
  topEdge.scale.x = 0;
  root.add(topEdge);
  ownedResources.push(topEdge.geometry);

  const sideEdge = new Mesh(
    new BoxGeometry(0.035, 1.78, 0.035),
    accentMaterial
  );
  sideEdge.position.set(1.38, 0.02, 0.06);
  sideEdge.scale.y = 0;
  root.add(sideEdge);
  ownedResources.push(sideEdge.geometry);

  const imagePlate = new Mesh(
    new BoxGeometry(2.62, 1.42, 0.035),
    paperMaterial
  );
  imagePlate.name = 'image-card-plate';
  imagePlate.position.set(0, 0.14, -0.04);
  root.add(imagePlate);
  ownedResources.push(imagePlate.geometry);

  const contentGroup = new Group();
  contentGroup.name = 'mesh-content';
  contentGroup.position.set(0, 0.16, 0.02);
  root.add(contentGroup);

  const initialScale = root.scale.clone();
  const baseY = root.position.y;

  const settle = gsap.timeline({ paused: true });
  settle
    .fromTo(
      root.scale,
      { x: initialScale.x * 1.04, y: initialScale.y * 1.04, z: initialScale.z * 1.04 },
      {
        x: initialScale.x,
        y: initialScale.y,
        z: initialScale.z,
        duration: 0.9,
        ease: 'power4.out'
      }
    );
  timelines.push(settle);

  const hoverLift = gsap.timeline({ paused: true });
  hoverLift.to(root.position, {
    y: baseY + 0.15,
    duration: 0.3,
    ease: 'power3.out'
  });
  timelines.push(hoverLift);

  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline
    .to(root.scale, {
      x: initialScale.x * 0.97,
      y: initialScale.y * 0.97,
      z: initialScale.z * 0.97,
      duration: 0.12,
      ease: 'power2.out'
    })
    .to(root.scale, {
      x: initialScale.x,
      y: initialScale.y,
      z: initialScale.z,
      duration: 0.28,
      ease: 'back.out(2)'
    });
  timelines.push(pressTimeline);

  const focusTimeline = gsap.timeline({ paused: true });
  focusTimeline
    .to(topEdge.scale, { x: 1, duration: 0.25, ease: 'power2.out' })
    .to(sideEdge.scale, { y: 1, duration: 0.25, ease: 'power2.out' }, '<');
  timelines.push(focusTimeline);

  const clearFocus = () => {
    focusTimeline.reverse();
  };

  root.userData.handlers = {
    hover: (active = true) => {
      if (active) hoverLift.play();
      else hoverLift.reverse();
    },
    click: () => {
      pressTimeline.restart();
      ctx.emit('hub-home.select', {
        node: root,
        parent: 'hub-home'
      });
    },
    focus: (active = true) => {
      if (active) focusTimeline.play();
      else clearFocus();
    },
    blur: clearFocus
  };

  root.userData.cleanup = () => {
    for (const timeline of timelines) {
      timeline.kill();
    }

    for (const cleanup of primitiveCleanups) {
      cleanup();
    }

    root.traverse((object) => {
      if (!object.isMesh) return;

      if (object.geometry && !ownedResources.includes(object.geometry)) {
        object.geometry.dispose();
      }

      const material = object.material;
      if (material && !ownedResources.includes(material)) {
        if (Array.isArray(material)) {
          for (const item of material) item?.dispose?.();
        } else {
          material.dispose?.();
        }
      }
    });

    for (const resource of ownedResources) {
      resource?.dispose?.();
    }

    root.clear();
  };

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (!gltf?.scene) return;

      const loadedScene = gltf.scene;
      loadedScene.name = 'gear-a-mesh';

      const bounds = new Box3().setFromObject(loadedScene);
      const center = new Vector3();
      const size = new Vector3();
      bounds.getCenter(center);
      bounds.getSize(size);

      loadedScene.position.sub(center);

      const maxDimension = Math.max(size.x, size.y, size.z, 0.001);
      const targetDimension = 1.35;
      const normalizedScale = targetDimension / maxDimension;
      loadedScene.scale.setScalar(normalizedScale);

      loadedScene.traverse((object) => {
        if (object.isMesh) {
          object.castShadow = true;
          object.receiveShadow = true;
        }
      });

      contentGroup.add(loadedScene);
      settle.restart();
    }).catch(() => {
      settle.restart();
    });
  } else {
    settle.restart();
  }

  return root;
}
